fn call_arguments<'a, Elements: IntoIterator<Item = Document<'a>>>(
    elements: Elements,
) -> Document<'a> {
    let elements = Itertools::intersperse(elements.into_iter(), break_(",", ", "))
        .collect_vec()
        .to_doc();
    if elements.is_empty() {
        return "()".to_doc();
    }
    docvec![
